def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])

    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def design_mat(sel, extra=()):
        return np.column_stack([S] + [X[:, j] for j in sel] + list(extra))

    R = np.corrcoef(X, rowvar=False)
    sel = []; base = ll(S)
    for k in range(MAX_DRIVERS):
        alpha = (0.05 if k == 0 else 0.01) / p
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.95 for s in sel): continue
            l1 = ll(design_mat(sel + [j]))
            if best is None or l1 > best[1]: best = (j, l1)
        if best is None: break
        if stats.chi2.sf(2 * (best[1] - base), 1) > alpha: break
        sel.append(best[0]); base = best[1]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        full = ll(design_mat(sel))
        pv = [stats.chi2.sf(2 * (full - ll(design_mat([s for s in sel if s != j]))), 1) for j in sel]
        worst = int(np.argmax(pv))
        if pv[worst] > 0.01 / p:
            sel.pop(worst); changed = True

    prods = []
    npairs = p * (p + 1) // 2
    base = ll(design_mat(sel))
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sel + [j for j in (a, b) if j not in sel]
            l0 = ll(design_mat(mains))
            l1 = ll(design_mat(mains, [X[:, a] * X[:, b]]))
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.01 / npairs: prods.append((pv, a, b))
    prods = sorted(prods)[:2]
    drivers = [ids[j] for j in sel]
    for _, a, b in prods:
        for j in (a, b):
            if ids[j] not in drivers: drivers.append(ids[j])
    drivers = drivers[:MAX_DRIVERS]
    cols = sorted(set(sel) | {j for _, a, b in prods for j in (a, b)})
    return Design(drivers=tuple(drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

